package com.ruoyi.ai.controller;import java.util.Map;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import com.ruoyi.ai.service.AiPageConfigService;import com.ruoyi.common.annotation.Log;import com.ruoyi.common.core.domain.AjaxResult;import com.ruoyi.common.enums.BusinessType;@RestController @RequestMapping("/ai/admin/pages")public class AiPageConfigController{private final AiPageConfigService service;public AiPageConfigController(AiPageConfigService s){service=s;}@PreAuthorize("@ss.hasPermi('ai:page:view')")@GetMapping public AjaxResult list(){return AjaxResult.success(service.list());}@PreAuthorize("@ss.hasPermi('ai:page:edit')")@Log(title="AI 页面能力",businessType=BusinessType.UPDATE)@PutMapping("/{pageId}/enabled")public AjaxResult enabled(@PathVariable Long pageId,@RequestBody Map<String,Boolean> body){service.setEnabled(pageId,Boolean.TRUE.equals(body.get("enabled")));return AjaxResult.success();}}
